/**
 * Solar Bold Duotone icons (Trae, 11/27/26), exported under the same names as the Lucide icons they replace, so a file
 * switches set by changing its import line. Used for the menu, page-title chips and navy icon squares; small button
 * glyphs (plus, x, trash, arrows) stay Lucide.
 *
 * Icons: "Solar" by 480 Design, https://www.figma.com/community/file/1166831539721848736 — licensed CC BY 4.0.
 * GENERATED from @iconify-json/solar. To add one: copy the icon's body from that package into a new line below.
 *
 * Two tones: the main shape is currentColor; the second tone carries class "rp-i2" (half strength by default,
 * its own colour inside the navy squares: see .rp-i2 in app/globals.css).
 */
import type { ReactNode, SVGProps } from 'react'

export type AppIcon = React.ComponentType<{ className?: string; strokeWidth?: number | string }>
type P = Omit<SVGProps<SVGSVGElement>, 'strokeWidth'> & { size?: number | string; strokeWidth?: number | string }

function make(body: ReactNode) {
  return function SolarIcon({ size, strokeWidth: _strokeWidth, ...rest }: P) {
    return <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width={size ?? 24} height={size ?? 24} fill="none" aria-hidden {...rest}>{body}</svg>
  }
}

